from pathlib import Path
import json
p=Path('automation/test/Test/Main.purs');s=p.read_text();rows=[
('audioGraphValues','PureScript Puppeteer renders actual connected gain and constant-source samples',"(async()=>{const c=new OfflineAudioContext(1,4,8000),source=c.createConstantSource(),gain=c.createGain();source.offset.value=2;gain.gain.value=0.25;source.connect(gain).connect(c.destination);source.start();const b=await c.startRendering();return JSON.stringify([b.length,Array.from(b.getChannelData(0))])})()",'[4,[0.5,0.5,0.5,0.5]]'),
('decodedValues','PureScript Puppeteer decodes actual PCM bytes into a genuine AudioBuffer',"(async()=>{const c=new OfflineAudioContext(1,2,8000),input=new ArrayBuffer(48),v=new DataView(input);for(const[at,text]of[[0,'RIFF'],[8,'WAVEfmt '],[36,'data']])for(let i=0;i<text.length;i++)v.setUint8(at+i,text.charCodeAt(i));v.setUint32(4,40,true);v.setUint32(16,16,true);v.setUint16(20,1,true);v.setUint16(22,1,true);v.setUint32(24,8000,true);v.setUint32(28,16000,true);v.setUint16(32,2,true);v.setUint16(34,16,true);v.setUint32(40,4,true);v.setInt16(44,16384,true);v.setInt16(46,-16384,true);const b=await c.decodeAudioData(input);return JSON.stringify([b instanceof AudioBuffer,b.sampleRate,Array.from(b.getChannelData(0)),input.byteLength])})()",'[true,8000,[0.5,-0.5],48]'),
('mediaValues','PureScript Puppeteer observes actual media transitions and synchronous events',"(async()=>{const v=document.createElement('video'),events=[];for(const type of['play','playing'])v.addEventListener(type,e=>events.push([e.type,e.isTrusted]));await v.play();const playing=[v.paused,v.readyState,v.networkState];v.pause();return JSON.stringify([events,playing,v.paused])})()",'[[["play",false],["playing",false]],[false,4,1],true]'),
('paymentValues','PureScript Puppeteer verifies the measured no-service Payment Request lifecycle',"(async()=>{const request=new PaymentRequest([{supportedMethods:'basic-card'}],{total:{label:'Total',amount:{currency:'USD',value:'1'}}}),available=await request.canMakePayment();let first,next;try{await request.show()}catch(e){first=e.name}try{await request.show()}catch(e){next=e.name}return JSON.stringify([request instanceof EventTarget,available,first,next])})()",'[true,false,"NotSupportedError","InvalidStateError"]'),
('databaseValues','PureScript Puppeteer writes and reads actual IndexedDB transactional bytes',"(async()=>{const name='red-panda-automation',db=await new Promise((resolve,reject)=>{const request=indexedDB.open(name,1);request.onupgradeneeded=()=>request.result.createObjectStore('records');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});await new Promise((resolve,reject)=>{const tx=db.transaction('records','readwrite');tx.objectStore('records').put({n:7,bytes:new Uint8Array([1,2])},'panda');tx.oncomplete=resolve;tx.onabort=()=>reject(tx.error)});const value=await new Promise((resolve,reject)=>{const request=db.transaction('records').objectStore('records').get('panda');request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});const result=JSON.stringify([value.n,Array.from(value.bytes),Object.getPrototypeOf(value)===Object.prototype]);db.close();await new Promise((resolve,reject)=>{const request=indexedDB.deleteDatabase(name);request.onsuccess=resolve;request.onerror=()=>reject(request.error)});return result})()",'[7,[1,2],true]'),
('sanitizedValues','PureScript Puppeteer sanitizes a real DOM subtree and removes unsafe handlers',"(()=>{const host=document.createElement('div');host.setHTML('<p>red<script>throw Error(1)</script><img src=x onerror=bad()><b>panda</b></p>');return JSON.stringify([host.textContent,host.querySelector('script')===null,host.querySelector('img').getAttribute('onerror'),host.firstChild.ownerDocument===document])})()",'["redpanda",true,null,true]'),
('animationValues','PureScript Puppeteer observes real animation cancellation promises and finish events',"(async()=>{const node=document.createElement('div'),a=node.animate([]);a.pause();const canceled=a.finished.catch(e=>e.name);a.cancel();const reason=await canceled,b=node.animate([]);b.pause();const event=new Promise(resolve=>b.onfinish=e=>resolve(e.isTrusted)),finished=b.finished;b.finish();const value=await finished;return JSON.stringify([a.playState,reason,b.playState,await event,value===b])})()",'["idle","AbortError","finished",true,true]'),
('popupValues','PureScript Puppeteer creates, writes, reuses and closes a genuine popup document',"(()=>{const popup=open('','automation-popup');popup.document.write('<body>red panda');popup.document.close();const result=[popup.opener===window,popup.document.body.textContent,popup===open('','automation-popup')];popup.close();result.push(popup.closed);return JSON.stringify(result)})()",'[true,"red panda",true,true]'),
('imageValues','PureScript Puppeteer follows the measured default image selection event lifecycle',"new Promise((resolve,reject)=>{const img=new Image();img.onerror=()=>reject(Error('unexpected image error'));img.onload=e=>resolve(JSON.stringify([img.complete,img.currentSrc===new URL('/not-fetched.png',location.href).href,img.naturalWidth,e.isTrusted,e.target===img]));img.src='/not-fetched.png'})",'[true,true,0,true,true]')]
addition=''
for variable,label,expression,expected in rows:addition+='        '+variable+' <- Browser.evaluateString page '+json.dumps(expression)+'\n        assert '+json.dumps(label)+' $ '+variable+' == '+json.dumps(expected)+'\n'
needle='        Browser.closePage page\n        log "PureScript Puppeteer integration: 71 checks passed"';assert s.count(needle)==1;s=s.replace(needle,addition+'        Browser.closePage page\n        log "PureScript Puppeteer integration: 80 checks passed"');p.write_text(s)
